// Exploratory SQLite writer-cache comparison only. Uses immutable validated base facts;
// not a replacement for the required publication/reindex acceptance methodology.
import Database from '/Users/xiyuanpan/prograph/node_modules/better-sqlite3/lib/index.js';import{mkdtemp,writeFile,rm}from'node:fs/promises';import path from'node:path';import os from'node:os';
import{SemanticStore}from'/Users/xiyuanpan/prograph/dist/core/semantic/store.js';import{SEMANTIC_SQL}from'/Users/xiyuanpan/prograph/dist/core/semantic/schema.js';
const source='/var/folders/j5/y1jjfjyd0sj9yh7n9qjk3wyc0000gn/T/prograph-scip-bench-bpTuoQ/.prograph/semantic.sqlite',root=await mkdtemp(path.join(os.tmpdir(),'prograph-cache-prototype-')),filename=path.join(root,'semantic.sqlite');const original=new Database(source,{readonly:true});await original.backup(filename);original.close();let stages={};const s=new SemanticStore(filename,{measure(stage,ms){stages[stage]=ms}});const runs=s.sql('SELECT run FROM sc_partitions WHERE snapshot=?').all(s.activeSnapshot()).map(r=>r.run),trials=[];
try{for(const cacheKiB of [16000,65536,16000]){s.db.pragma('cache_size=-'+cacheKiB);s.db.transaction(()=>{s.db.exec("DELETE FROM sc_meta WHERE key='active';UPDATE sc_snapshots SET parent=NULL;DELETE FROM sc_snapshots;DELETE FROM sc_visibility;DROP TABLE sc_call_epochs;DROP TABLE sc_claim_navigation");s.db.exec(SEMANTIC_SQL)})();stages={};const start=performance.now(),snapshot=s.publish(runs);const result={cacheKiB,snapshot,ms:performance.now()-start,stages,visible:s.sql('SELECT COUNT(*) AS n FROM sc_active WHERE snapshot=?').get(snapshot).n};trials.push(result);console.log(JSON.stringify(result));}
const report={scope:'Exploratory only: repeated complete first navigation construction with 16/64/16 MiB writer caches; no producer or reindex staging. Same base facts, serial order and warm filesystem/allocator confounding; informs an implementation tradeoff, not acceptance numbers.',node:process.version,root,trials,integrity:s.db.pragma('integrity_check',{simple:true}),foreignKeys:s.db.pragma('foreign_key_check'),nodePeakRssKiB:process.resourceUsage().maxRSS};await writeFile('/private/tmp/prograph-stage5-cache-prototype.json',JSON.stringify(report,null,2)+'\n');}finally{s.close();await rm(root,{recursive:true,force:true})}
